(function(){
  'use strict';
  var H=window.HomeIA2;if(!H)return;var one=H.one,all=H.all,make=H.make,text=H.text,c=H.c;
  function unique(nodes){return nodes.filter(function(n,i,a){return n&&a.indexOf(n)===i})}
  function hero(){var h=one('.premium-home-hero');if(!h)return;var box=one('.premium-hero-copy',h);if(box&&!one('.ia-hero-layer',box))box.insertBefore(make('div','ia-hero-layer','<b>01</b><span>'+c.hero+'</span>'),box.firstChild);var actions=one('.premium-hero-actions',h);if(!actions)return;var links=all('a',actions),targets=['#news-flash','#news-hearing-notes','#global-protection-wall'];while(links.length<3){var x=make('a',links.length?'btn art-secondary':'btn art-primary');actions.appendChild(x);links.push(x)}links.slice(0,3).forEach(function(a,i){a.href=targets[i];a.textContent=c.actions[i];a.dataset.iaHeroAction=String(i+1)})}
  function priority(){var s=one('.home-priority-strip');if(!s)return;text(one('.home-priority-shell>header small',s),c.nowEye);text(one('.home-priority-shell>header h2',s),c.nowTitle);var g=one('.home-priority-links .is-guest',s);if(!g)return;g.classList.remove('is-guest');g.classList.add('is-latest');g.href='#news-flash';text(one('.home-priority-icon',g),'✦');text(one('small',g),c.latest[0]);text(one('strong',g),c.latest[1]);text(one('em',g),c.latest[2]);text(one(':scope>b',g),'↓')}
  function chapter(id,cls,cp,nodes){nodes=unique(nodes);if(!nodes.length||document.getElementById(id))return;var first=nodes[0],wrap=make('div','ia-chapter '+cls),head=make('header','ia-chapter-head');head.innerHTML='<span class="ia-chapter-index"><b>'+cp[0]+'</b><small>'+cp[1]+'</small></span><div class="ia-chapter-copy"><small>OFFICIAL SITE · INFORMATION PATH</small><h2>'+cp[2]+'</h2><p>'+cp[3]+'</p></div>';wrap.id=id;wrap.appendChild(head);first.parentNode.insertBefore(wrap,first);nodes.forEach(function(n){wrap.appendChild(n)})}
  function chapters(){chapter('ia-now','ia-chapter-now',c.chapters[0],[one('.home-priority-strip'),one('#news-flash'),one('#news-hearing'),one('#news-hearing-notes')]);chapter('ia-reading','ia-chapter-reading',c.chapters[1],[one('#home-special-features'),one('.home-social-cases-section'),one('#home-historical-cases')]);chapter('ia-action','ia-chapter-action',c.chapters[2],[one('#global-protection-wall'),one('#news-activity')]);chapter('ia-about','ia-chapter-about',c.chapters[3],[one('.remember-kaikai-section'),one('.impact-dashboard-section'),one('.mission-section'),one('.social-preview-section'),one('.primary-brand-section'),one('.belief-footer-section')])}
  function wall(){var s=one('#global-protection-wall');if(!s)return;s.classList.add('ia-wall-hub');var container=one('.container',s)||s,card=one('.home-protection-wall-card',s);text(one('#globalProtectionWallTitle',s),c.wall);if(!one('.ia-wall-purpose',s)){var p=make('div','ia-wall-purpose','<span>'+c.wallPair[0]+'</span><i aria-hidden="true">×</i><span>'+c.wallPair[1]+'</span>');if(card)container.insertBefore(p,card)}if(!one('.ia-wall-actions',s)){var a=make('div','ia-wall-actions');a.innerHTML='<a class="ia-wall-action is-guest" href="./global-protection-wall/?section=guest-message"><i aria-hidden="true">♡</i><span><strong>'+c.guest[0]+'</strong><small>'+c.guest[1]+'</small></span><b aria-hidden="true">→</b></a><a class="ia-wall-action is-member" href="./global-protection-wall/?section=member-submit"><i aria-hidden="true">✎</i><span><strong>'+c.member[0]+'</strong><small>'+c.member[1]+'</small></span><b aria-hidden="true">→</b></a>';container.appendChild(a)}}
  function liveCases(){var s=one('.home-social-cases-section');if(!s)return;s.classList.add('ia-live-cases');text(one('.home-social-cases-copy p',s),c.live[1]);all('.home-case-reel-card',s).forEach(function(card){var box=one('.home-case-reel-copy',card);if(!box||one('.ia-live-case-kicker',box))return;box.insertBefore(make('span','ia-live-case-kicker',c.live[0]),box.firstChild);box.appendChild(make('span','ia-live-case-link',c.live[2]))})}
  H.features.layout=function(){hero();priority();chapters();wall();liveCases()};
})();
